#include <string>
#include <algorithm>
using namespace std;

class Solution {
public:
    int minOperations(string s) {
        int c0 = 0;
        int n = s.size();
        for (int i = 0; i < n; ++i) {
            char expected = (i % 2 == 0) ? '0' : '1';
            if (s[i] != expected) c0++;
        }
        return min(c0, n - c0);
    }
};

class Solution {
    public int minOperations(String s) {
        int c0 = 0;
        int n = s.length();
        for (int i = 0; i < n; ++i) {
            char expected = (i % 2 == 0) ? '0' : '1';
            if (s.charAt(i) != expected) c0++;
        }
        return Math.min(c0, n - c0);
    }
}

/**
 * @param {string} s
 * @return {number}
 */
var minOperations = function(s) {
    let c0 = 0;
    const n = s.length;
    for (let i = 0; i < n; ++i) {
        const expected = (i % 2 === 0) ? '0' : '1';
        if (s[i] !== expected) c0++;
    }
    return Math.min(c0, n - c0);
};
